def ngrams(s, n=3):
    return set(s[i:i+n] for i in range(len(s)-n+1))

def jaccard(a, b):
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)

samples = ["我爱机器学习", "机器学习很有趣", "今天天气真好", "我爱机器学习模型"]
sigs = [ngrams(s, 3) for s in samples]
keep = [0]
for i in range(1, len(samples)):
    dup = any(jaccard(sigs[i], sigs[j]) >= 0.5 for j in keep)
    if not dup:
        keep.append(i)
print("保留索引:", keep)
print("保留样本:", [samples[i] for i in keep])
